    77→    internal static void StartEncoding(ExportProject project, ExportPreset preset)
    78→    {
    79→        //If the user still wants an encoder window, here's when it should be opened.
    80→        if (UserSettings.All.DisplayEncoder)
    81→            Application.Current.Dispatcher?.Invoke(() => Encoder.Start(preset.Scale));
    82→
    83→        //Creates the Cancellation Token
    84→        var cancellationTokenSource = new CancellationTokenSource();
    85→        CancellationTokenList.Add(cancellationTokenSource);
    86→
    87→        var context = Application.Current.Dispatcher?.Invoke(TaskScheduler.FromCurrentSynchronizationContext);
    88→
    89→        //Creates Task and send the Task Id.
    90→        var taskId = -1;
    91→        var task = new Task(async () =>
    92→        {
    93→            //ReSharper disable once AccessToModifiedClosure
    94→            await Encode(project, preset, taskId, cancellationTokenSource);
    95→
    96→        }, cancellationTokenSource.Token, TaskCreationOptions.LongRunning);
    97→        taskId = task.Id;
    98→
    99→        #region Error handling
   100→
   101→        task.ContinueWith(t =>
   102→        {
   103→            var aggregateException = t.Exception;
   104→            aggregateException?.Handle(exception => true);
   105→
   106→            Update(taskId, EncodingStatus.Error, null, false, t.Exception);
   107→            LogWriter.Log(t.Exception, "Encoding error.");
   108→
   109→        }, CancellationToken.None, TaskContinuationOptions.OnlyOnFaulted, context);
   110→
   111→        #endregion
   112→
   113→        //Adds the encoding to the list.
   114→        Encodings.Add(new EncodingItem
   115→        {
   116→            Id = taskId,
   117→            OutputType = preset.Type,
   118→            Text = LocalizationHelper.Get("S.Encoder.Starting"),
   119→            FrameCount = project.FrameCount,
   120→            TokenSource = cancellationTokenSource
   121→        });
   122→
   123→        try
   124→        {
   125→            TaskList.Add(task);
   126→            task.Start();
   127→        }
   128→        catch (Exception ex)
   129→        {
   130→            ErrorDialog.Ok("Task Error", "Unable to start the encoding task", "A generic error occurred while trying to start the encoding task.", ex);
   131→            LogWriter.Log(ex, "Error while starting the task.");
   132→        }
   133→
   134→        //Application.Current.Dispatcher.Invoke(() => Refresh(taskId));
   135→        Application.Current.Dispatcher?.Invoke(() => EncodingAdded(taskId));
   136→    }
