   208→    /// <summary>
   209→    /// Updates the status of the encoding of a current item.
   210→    /// </summary>
   211→    /// <param name="status">The current status.</param>
   212→    /// <param name="id">The unique ID of the item.</param>
   213→    /// <param name="fileName">The name of the output file.</param>
   214→    /// <param name="isIndeterminate">The state of the progress bar.</param>
   215→    /// <param name="exception">The exception details of the error.</param>
   216→    /// <param name="maxSteps">Optionally sets the maximum steps of the processing if (<paramref name="status"/> is <see cref="EncodingStatus.Processing"/>).</param>
   217→    internal static void Update(int id, EncodingStatus status, string fileName = null, bool isIndeterminate = false, Exception exception = null, int? maxSteps = null)
   218→    {
   219→        var item = Encodings.FirstOrDefault(x => x.Id == id);
   220→
   221→        if (item == null)
   222→            return;
   223→
   224→        var wasStatusUpdated = item.Status != status;
   225→
   226→        item.Status = status;
   227→        item.IsIndeterminate = isIndeterminate;
   228→
   229→        switch (status)
   230→        {
   231→            case EncodingStatus.Processing:
   232→                item.Text = String.Format(LocalizationHelper.Get("S.Encoder.Processing"), fileName == null ? String.Empty : Path.GetFileName(fileName));
   233→                if (maxSteps.HasValue)
   234→                    item.FrameCount = maxSteps.Value;
   235→                break;
   236→            case EncodingStatus.Completed:
   237→            {
   238→                if (fileName == null)
   239→                    break;
   240→
   241→                if (File.Exists(fileName))
   242→                {
   243→                    var fileInfo = new FileInfo(fileName);
   244→                    fileInfo.Refresh();
   245→
   246→                    item.SizeInBytes = fileInfo.Length;
   247→                    item.OutputFilename = fileName;
   248→                    item.SavedToDisk = true;
   249→                }
   250→
   251→                break;
   252→            }
   253→            case EncodingStatus.Error:
   254→            {
   255→                item.Exception = exception;
   256→                break;
   257→            }
   258→        }
   259→
   260→        Application.Current.Dispatcher.Invoke(() => EncodingUpdated(item, wasStatusUpdated));
   261→    }
   262→
   263→    internal static void UpdateMultiple(int id, EncodingStatus status, List<string> fileNames, bool isIndeterminate = false)
   264→    {
   265→        var item = Encodings.FirstOrDefault(x => x.Id == id);
   266→
   267→        if (item == null)
   268→            return;
   269→
   270→        var wasStatusUpdated = item.Status != status;
   271→
   272→        item.Status = status;
   273→        item.IsIndeterminate = isIndeterminate;
   274→        item.AreMultipleFiles = true;
   275→
   276→        if (status == EncodingStatus.Completed && fileNames?.Any() == true)
   277→        {
   278→            foreach (var fileInfo in fileNames.Where(File.Exists).Select(fileName => new FileInfo(fileName)))
   279→            {
   280→                fileInfo.Refresh();
   281→
   282→                item.SizeInBytes += fileInfo.Length;
   283→            }
   284→
   285→            if (item.SizeInBytes > 0)
   286→            {
   287→                item.OutputFilename = fileNames.FirstOrDefault();
   288→                item.SavedToDisk = true;
   289→            }
   290→        }
   291→
   292→        Application.Current.Dispatcher.Invoke(() => EncodingUpdated(item, wasStatusUpdated));
   293→    }
