   366→    internal static void RemoveEncodings(Predicate<EncodingItem> match)
   367→    {
   368→        var list = Encodings.Where(match.Invoke).ToList();
   369→
   370→        foreach (var encoding in list)
   371→        {
   372→            Encodings.Remove(encoding);
   373→
   374→            TaskList.FirstOrDefault(f => f.Id == encoding.Id)?.Dispose();
   375→            encoding.TokenSource.Dispose();
   376→
   377→            TaskList.RemoveAll(r => r.Id == encoding.Id);
