   418→            item.SizeInBytes = current.SizeInBytes;
   419→            item.OutputFilename = current.OutputFilename;
   420→            item.SavedToDisk = current.SavedToDisk;
   421→            item.AreMultipleFiles = current.AreMultipleFiles;
   422→            item.Exception = current.Exception;
   423→
   424→            item.Uploaded = current.Uploaded;
   425→            item.UploadLink = current.UploadLink;
   426→            item.UploadLinkDisplay = current.UploadLinkDisplay;
   427→            item.DeletionLink = current.DeletionLink;
   428→            item.UploadTaskException = current.UploadTaskException;
   429→
   430→            item.CopiedToClipboard = current.CopiedToClipboard;
   431→            item.CopyTaskException = current.CopyTaskException;
   432→
   433→            item.CommandExecuted = current.CommandExecuted;
   434→            item.Command = current.Command;
   435→            item.CommandOutput = current.CommandOutput;
   436→            item.CommandTaskException = current.CommandTaskException;
   437→
   438→            item.TimeToAnalyze = current.TimeToAnalyze;
