   484→
   485→    private static async Task Encode(ExportProject project, ExportPreset preset, int id, CancellationTokenSource tokenSource)
   486→    {
   487→        var processing = LocalizationHelper.Get("S.Encoder.Processing");
   488→        var watch = new Stopwatch();
   489→        watch.Start();
   490→
   491→        try
   492→        {
   493→            #region File naming
   494→
   495→            if (preset.PickLocation)
   496→            {
   497→                preset.FullPath = Path.Combine(preset.OutputFolder, preset.ResolvedFilename + (preset.Extension ?? preset.DefaultExtension));
   498→            }
   499→            else
   500→            {
   501→                preset.OutputFolder = Path.GetTempPath(); //Get path where the cache is stored instead.
   502→                preset.OutputFilename = Guid.NewGuid() + preset.Extension;
   503→                preset.FullPath = Path.Combine(preset.OutputFolder, preset.OutputFilename);
   504→
   505→                //If somehow this happens, try again. TODO: File should be created on the spot, to properly prevent this issue.
   506→                if (File.Exists(Path.Combine(preset.OutputFilename, preset.OutputFilename)))
   507→                {
   508→                    preset.OutputFilename = Guid.NewGuid() + preset.Extension;
   509→                    preset.FullPath = Path.Combine(preset.OutputFolder, preset.OutputFilename);
   510→                }
   511→            }
   512→
   513→            #endregion
   514→
   515→            switch (preset.Type)
   516→            {
   517→                case ExportFormats.Apng:
   518→                {
   519→                    #region Apng
   520→
   521→                    switch (preset.Encoder)
   522→                    {
   523→                        case EncoderTypes.ScreenToGif:
   524→                        {
   525→                            if (preset is not EmbeddedApngPreset embApngPreset)
   526→                                return;
   527→
   528→                            #region Cut/Paint Unchanged Pixels
   529→
   530→                            if (embApngPreset.DetectUnchanged)
   531→                            {
   532→                                Update(id, 0, LocalizationHelper.Get("S.Encoder.Analyzing"));
   533→
   534→                                if (embApngPreset.PaintTransparent)
   535→                                    project.FramesFiles = ImageMethods.PaintTransparentAndCut(project.FramesFiles, Colors.Transparent, id, tokenSource);
   536→                                else
   537→                                    project.FramesFiles = ImageMethods.CutUnchanged(project.FramesFiles, id, tokenSource);
   538→
   539→                                Update(id, 0, watch.Elapsed);
   540→                                watch.Restart();
