  1333→    private static async Task EncodeKGySoftGif(KGySoftGifPreset preset, IList<IFrame> frames, int id, CancellationToken cancellationToken)
  1334→    {
  1335→        #region Local Methods
  1336→
  1337→        IEnumerable<IReadableBitmapData> FramesIterator()
  1338→        {
  1339→            for (int i = 0; i < frames.Count; i++)
  1340→            {
  1341→                Update(id, i);
  1342→                using var bitmap = new Bitmap(frames[i].Path);
  1343→                using var bitmapData = bitmap.GetReadableBitmapData();
  1344→                yield return bitmapData;
  1345→            }
  1346→        }
  1347→
  1348→        #endregion
  1349→
  1350→        // A little cheating for PingPong mode: though the encoder could handle it, we convert it explicitly to a simple forward loop so
  1351→        // we can update the progress in FramesIterator and don't need to pass a DrawingProgress implementation to TaskConfig.Progress
  1352→        var animationMode = (AnimationMode)preset.RepeatCount;
  1353→
  1354→        if (animationMode == AnimationMode.PingPong)
  1355→        {
  1356→            animationMode = AnimationMode.Repeat;
  1357→
  1358→            for (int i = frames.Count - 2; i > 0; i--)
  1359→                frames.Add(frames[i]);
  1360→        }
  1361→
  1362→        Update(id, EncodingStatus.Processing, maxSteps: frames.Count);
  1363→        var config = new AnimatedGifConfiguration(FramesIterator(), frames.Select(f => TimeSpan.FromMilliseconds(f.Delay)))
  1364→        {
  1365→            AllowDeltaFrames = preset.AllowDeltaFrames,
  1366→            AllowClippedFrames = preset.AllowClippedFrames,
  1367→            AnimationMode = animationMode,
  1368→            DeltaTolerance = preset.DeltaTolerance,
  1369→            SizeHandling = AnimationFramesSizeHandling.Center,
  1370→            Quantizer = QuantizerDescriptor.Create(preset.QuantizerId, preset),
  1371→            Ditherer = DithererDescriptor.Create(preset.DithererId, preset),
  1372→        };
  1373→
  1374→        await using var stream = File.Create(preset.FullPath, Constants.BufferSize);
  1375→        await KGySoftGifEncoder.EncodeAnimationAsync(config, stream, new TaskConfig
  1376→        {
  1377→            CancellationToken = cancellationToken,
  1378→            ThrowIfCanceled = false
  1379→        });
  1380→
  1381→        if (!cancellationToken.IsCancellationRequested)
  1382→            await stream.FlushAsync(cancellationToken);
  1383→    }
