  1669→                    if (videoPreset.VideoCodec == VideoCodecs.Mpeg4)
  1670→                        firstPass += "-vtag xvid ";
  1671→                    else if (videoPreset.VideoCodec == VideoCodecs.Vp9)
  1672→                        firstPass += "-tile-columns 6 -frame-parallel 1 -auto-alt-ref 1 -lag-in-frames 25 ";
  1673→
  1674→                    //Codec preset.
  1675→                    if (videoPreset.CodecPreset != VideoCodecPresets.Default && videoPreset.CodecPreset != VideoCodecPresets.None && videoPreset.CodecPreset != VideoCodecPresets.NotSelected)
  1676→                    {
  1677→                        if (videoPreset.VideoCodec is VideoCodecs.SvtAv1 or VideoCodecs.Rav1E)
  1678→                            firstPass += $"-preset {(int) videoPreset.CodecPreset} ";
  1679→                        else
  1680→                            firstPass += $"-preset {videoPreset.CodecPreset.GetLowerDescription()} ";
  1681→                    }
  1682→
  1683→                    //Pixel format.
  1684→                    if (videoPreset.PixelFormat != VideoPixelFormats.Auto)
  1685→                        firstPass += $"-pix_fmt {videoPreset.PixelFormat.GetLowerDescription()} ";
  1686→
  1687→                    //Workaround, makes the size to be divisible by two.
  1688→                    firstPass += "-vf \"scale=trunc(iw/2)*2:trunc(ih/2)*2\" "; //"scale=iw+mod(iw,2):ih+mod(ih,2):flags=neighbor" OR "pad=width={W}:height={H}:x=0:y=0:color=black"
  1689→
  1690→                    //CRF.
  1691→                    if (videoPreset.ConstantRateFactor > 0)
  1692→                        firstPass += $"-crf {videoPreset.ConstantRateFactor.Value.ToString(CultureInfo.InvariantCulture)} ";
  1693→
  1694→                    //Bitrate.
  1695→                    if (videoPreset.IsVariableBitRate)
  1696→                        firstPass += $"-q:v {videoPreset.QualityLevel.ToString(CultureInfo.InvariantCulture)} ";
  1697→                    else
  1698→                    {
  1699→                        if (videoPreset.BitRate > 0)
  1700→                            firstPass += $"-b:v {videoPreset.BitRate.ToString(CultureInfo.InvariantCulture)}{videoPreset.BitRateUnit.GetDescription()} ";
  1701→                        else if (videoPreset.BitRate == 0 && (videoPreset.VideoCodec == VideoCodecs.Vp8 || videoPreset.VideoCodec == VideoCodecs.Vp9))
  1702→                            firstPass += "-b:v 0 ";
  1703→                    }
  1704→
  1705→                    //Minimum bitrate.
  1706→                    if (videoPreset.MinimumBitRate > 0)
  1707→                        firstPass += $"-minrate {videoPreset.MinimumBitRate.ToString(CultureInfo.InvariantCulture)}{videoPreset.MinimumBitRateUnit.GetDescription()} ";
  1708→
  1709→                    //Maximum bitrate.
  1710→                    if (videoPreset.MaximumBitRate > 0)
  1711→                        firstPass += $"-maxrate {videoPreset.MaximumBitRate.ToString(CultureInfo.InvariantCulture)}{videoPreset.MaximumBitRateUnit.GetDescription()} ";
  1712→
  1713→                    //Buffer size.
  1714→                    if (videoPreset.RateControlBuffer > 0)
  1715→                        firstPass += $"-bufsize {videoPreset.RateControlBuffer.ToString(CultureInfo.InvariantCulture)}{videoPreset.RateControlBufferUnit.GetDescription()} ";
  1716→
  1717→                    //First pass adjustments.
  1718→                    if (videoPreset.Pass > 1)
  1719→                    {
  1720→                        if (videoPreset.VideoCodec == VideoCodecs.X265)
  1721→                            firstPass += "-x265-params pass=1 ";
  1722→                        else
  1723→                            firstPass += "-pass 1 ";
  1724→
  1725→                        firstPass += $"-passlogfile \"{preset.FullPath}\" ";
  1726→                    }
  1727→
  1728→                    //Framerate.
  1729→                    if (videoPreset.Framerate != Framerates.Auto)
  1730→                        firstPass += $"-r {(videoPreset.Framerate == Framerates.Custom ? videoPreset.CustomFramerate.ToString(CultureInfo.InvariantCulture) : videoPreset.Framerate.GetLowerDescription())} ";
  1731→
  1732→                    //Format and output.
  1733→                    firstPass += $"-f {preset.Type.ToString().ToLower().Replace("mkv", "matroska")} ";
  1734→
  1735→                    //Vsync
  1736→                    if (videoPreset.Vsync != Vsyncs.Off)
  1737→                    {
  1738→                        if (UserSettings.All.FfmpegVersion == SupportedFFmpegVersions.Version6)
  1739→                            firstPass += "-fps_mode " + videoPreset.Vsync.GetLowerDescription();
  1740→                        else
  1741→                            firstPass += "-vsync " + videoPreset.Vsync.GetLowerDescription();
  1742→                    }
  1743→
  1744→                    firstPass += " {O}";
  1745→
  1746→                    //Second pass, using a similar command with some adjustments.
  1747→                    if (videoPreset.Pass > 1)
  1748→                        secondPass = "-hide_banner " + firstPass.Replace("-pass 1", "-pass 2").Replace("pass=1", "pass=2");
  1749→                }
  1750→
  1751→                break;
  1752→
  1753→                #endregion
  1754→            }
  1755→        }
  1756→
  1757→        //Replace special params.
  1758→        firstPass = firstPass.Replace("{I}", $"-safe 0 -f concat -i \"file:{concatFile}\"").Replace("{O}", $"-y \"{preset.FullPath}\"")
  1759→            .Replace("{H}", preset.Height.DivisibleByTwo().ToString(CultureInfo.InvariantCulture)).Replace("{W}", preset.Width.DivisibleByTwo().ToString(CultureInfo.InvariantCulture));
  1760→
  1761→        secondPass = secondPass.Replace("{I}", $"-safe 0 -f concat -i \"file:{concatFile}\"").Replace("{O}", $"-y \"{preset.FullPath}\"")
  1762→            .Replace("{H}", preset.Height.DivisibleByTwo().ToString(CultureInfo.InvariantCulture)).Replace("{W}", preset.Width.DivisibleByTwo().ToString(CultureInfo.InvariantCulture));
  1763→
  1764→        var process = new ProcessStartInfo(UserSettings.All.FfmpegLocation)
  1765→        {
  1766→            Arguments = firstPass,
  1767→            CreateNoWindow = true,
  1768→            ErrorDialog = false,
  1769→            UseShellExecute = false,
  1770→            RedirectStandardError = true
  1771→        };
  1772→
  1773→        var log = "";
  1774→        using (var pro = Process.Start(process))
  1775→        {
  1776→            var indeterminate = true;
  1777→
  1778→            Update(id, 0, LocalizationHelper.Get("S.Encoder.Analyzing"));
  1779→
  1780→            while (!pro.StandardError.EndOfStream)
  1781→            {
  1782→                if (tokenSource.IsCancellationRequested)
  1783→                {
  1784→                    pro.Kill();
  1785→                    return;
  1786→                }
  1787→
  1788→                var line = pro.StandardError.ReadLine() ?? "";
  1789→                log += Environment.NewLine + line;
  1790→
  1791→                var split = line.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
  1792→                var containsDuplicatedFrames = line.Contains("dup=");
  1793→
  1794→                for (var block = 0; block < split.Length; block++)
  1795→                {
  1796→                    //frame=  321 fps=170 q=-0.0 Lsize=      57kB time=00:00:14.85 bitrate=  31.2kbits/s speed=7.87x
  1797→                    if (!split[block].StartsWith("frame="))
  1798→                        continue;
  1799→
  1800→                    if (int.TryParse(split[block + 1], out var frame))
