  1838→
  1839→            log += Environment.NewLine + SecondPassFfmpeg(secondPass, id, tokenSource, LocalizationHelper.Get("S.Encoder.Processing.Second"));
  1840→
  1841→            EraseSecondPassLogs(preset.FullPath);
  1842→        }
