  1844→        if (!fileInfo.Exists || fileInfo.Length == 0)
  1845→            throw new Exception($"Error while encoding the {preset.Type} with FFmpeg.") { HelpLink = $"Command:\n\r{firstPass + Environment.NewLine + secondPass}\n\rResult:\n\r{log}" };
  1846→    }
