   563→    private void CalculateColorTableSize()
   564→    {
   565→        //Logical Screen Description, Number of Colors, Byte length.
   566→        //0 = 2 = 6
   567→        //1 = 4 = 12
   568→        //2 = 8 = 24
   569→        //3 = 16 = 48
   570→        //4 = 32 = 96
   571→        //5 = 64 = 192
   572→        //6 = 128 = 384
   573→        //7 = 256 = 768
   574→        //The inverse calculation is: 2^(N + 1) 
   575→        //and x3 for the byte length.
   576→
   577→        //If the colorsCount == 1, 
   578→        //return zero instead of calculating it, because of the Log(0) call.
   579→        //The "-1" assures that the count stays in range.
   580→        ColorTableSize = ColorTable.Count > 1 ? (int)Math.Log(ColorTable.Count - 1, 2) : 0;
