     1→using System.Drawing;
     2→using System.Drawing.Imaging;
     3→using System.IO;
     4→
     5→namespace ScreenToGif.Util.Codification.Gif.LegacyEncoder;
     6→
     7→/// <summary>
     8→/// Encodes multiple images as an animated gif to a stream. <br />
     9→/// ALWAYS wire this up in a "using" block <br />
    10→/// Disposing the encoder will complete the file. <br />
    11→/// Uses default .net GIF encoding and adds animation headers.
    12→/// </summary>
    13→public sealed class GifEncoder : IDisposable
    14→{
    15→    #region Header Constants
    16→
    17→    private const string FileType = "GIF";
    18→
    19→    private const string FileVersion = "89a";
    20→
    21→    private const byte FileTrailer = 0x3b;
    22→
    23→    private const int ApplicationExtensionBlockIdentifier = 0xff21;
    24→
    25→    private const byte ApplicationBlockSize = 0x0b;
    26→
    27→    private const string ApplicationIdentification = "NETSCAPE2.0";
    28→
    29→    private const int GraphicControlExtensionBlockIdentifier = 0xf921;
    30→
    31→    private const byte GraphicControlExtensionBlockSize = 0x04;
    32→
    33→    private const long SourceGlobalColorInfoPosition = 10;
    34→
    35→    private const long SourceGraphicControlExtensionPosition = 781;
    36→
    37→    private const long SourceGraphicControlExtensionLength = 8;
    38→
    39→    private const long SourceImageBlockPosition = 789;
    40→
    41→    private const long SourceImageBlockHeaderLength = 11;
    42→
    43→    private const long SourceColorBlockPosition = 13;
    44→
    45→    private const long SourceColorBlockLength = 768;
    46→
    47→    #endregion
    48→
    49→    private bool _isFirstImage = true;
    50→
    51→    private int? _width;
    52→
    53→    private int? _height;
    54→
    55→    private int? _repeatCount;
    56→
    57→    private readonly Stream _stream;
    58→
    59→    /// <summary>
    60→    /// Frame delay for the frame.
    61→    /// </summary>
    62→    public TimeSpan FrameDelay { get; set; }
    63→
    64→    /// <summary>
    65→    /// Encodes multiple images as an animated gif to a stream. <br />
    66→    /// ALWAYS wire this in a using block <br />
    67→    /// Disposing the encoder will complete the file. <br />
    68→    /// Uses default .net GIF encoding and adds animation headers.
    69→    /// </summary>
    70→    /// <param name="stream">The stream that will be written to.</param>
    71→    /// <param name="width">Sets the width for this gif or null to use the first frame's width.</param>
    72→    /// <param name="height">Sets the height for this gif or null to use the first frame's height.</param>
    73→    /// <param name="repeatCount">The repeat count of the animation</param>
    74→    public GifEncoder(Stream stream, int? width = null, int? height = null, int? repeatCount = null)
    75→    {
    76→        _stream = stream;
    77→        _width = width;
    78→        _height = height;
    79→        _repeatCount = repeatCount;
    80→    }
    81→
    82→    /// <summary>
    83→    /// Adds a frame to this animation.
    84→    /// </summary>
    85→    /// <param name="img">The image to add</param>
    86→    /// <param name="x">The positioning x offset this image should be displayed at.</param>
    87→    /// <param name="y">The positioning y offset this image should be displayed at.</param>
    88→    /// <param name="frameDelay">The delay of the redraw of the next frame.</param>
    89→    public void AddFrame(Image img, int x = 0, int y = 0, TimeSpan? frameDelay = null)
    90→    {
    91→        using (var gifStream = new MemoryStream())
    92→        {
    93→            img.Save(gifStream, ImageFormat.Gif);
    94→
    95→            if (_isFirstImage) //Steal the global color table info
    96→                InitHeader(gifStream, img.Width, img.Height);
    97→
    98→            WriteGraphicControlBlock(gifStream, frameDelay.GetValueOrDefault(FrameDelay));
    99→            WriteImageBlock(gifStream, !_isFirstImage, x, y, img.Width, img.Height);
   100→        }
   101→
   102→        _isFirstImage = false;
   103→    }
   104→
   105→    private void InitHeader(Stream sourceGif, int w, int h)
   106→    {
   107→        // File Header
   108→        WriteString(FileType);
   109→        WriteString(FileVersion);
   110→        WriteShort(_width.GetValueOrDefault(w)); // Initial Logical Width
   111→        WriteShort(_height.GetValueOrDefault(h)); // Initial Logical Height
   112→
   113→        sourceGif.Position = SourceGlobalColorInfoPosition;
   114→        WriteByte(sourceGif.ReadByte()); // Global Color Table Info
   115→        WriteByte(0); // Background Color Index
   116→        WriteByte(0); // Pixel aspect ratio
   117→        WriteColorTable(sourceGif);
   118→
   119→        if (_repeatCount < 0)
   120→            return;
   121→
   122→        //App Extension Header
   123→        WriteShort(ApplicationExtensionBlockIdentifier);
   124→        WriteByte(ApplicationBlockSize);
   125→        WriteString(ApplicationIdentification);
   126→        WriteByte(3); // Application block length
   127→        WriteByte(1);
   128→        WriteShort(_repeatCount.GetValueOrDefault(0)); // Repeat count for images.
   129→        WriteByte(0); // terminator
   130→    }
   131→
   132→    private void WriteColorTable(Stream sourceGif)
   133→    {
   134→        sourceGif.Position = SourceColorBlockPosition; // Locating the image color table
   135→        var colorTable = new byte[SourceColorBlockLength];
   136→
   137→        sourceGif.Read(colorTable, 0, colorTable.Length);
   138→        _stream.Write(colorTable, 0, colorTable.Length);
   139→    }
   140→
   141→    private void WriteGraphicControlBlock(Stream sourceGif, TimeSpan frameDelay)
   142→    {
   143→        sourceGif.Position = SourceGraphicControlExtensionPosition; // Locating the source GCE
   144→        var blockhead = new byte[SourceGraphicControlExtensionLength];
   145→        sourceGif.Read(blockhead, 0, blockhead.Length); // Reading source GCE
   146→
   147→        WriteShort(GraphicControlExtensionBlockIdentifier); // Identifier
   148→        WriteByte(GraphicControlExtensionBlockSize); // Block Size
   149→        WriteByte(blockhead[3] & 0xf7 | 0x08); // Setting disposal flag
   150→        WriteShort(Convert.ToUInt16(frameDelay.TotalMilliseconds / 10)); // Setting frame delay
   151→        WriteByte(blockhead[6]); // Transparent color index
   152→        WriteByte(0); // Terminator
   153→    }
   154→
   155→    private void WriteImageBlock(Stream sourceGif, bool includeColorTable, int x, int y, int h, int w)
   156→    {
   157→        sourceGif.Position = SourceImageBlockPosition; // Locating the image block
   158→        var header = new byte[SourceImageBlockHeaderLength];
   159→        sourceGif.Read(header, 0, header.Length);
   160→
   161→        WriteByte(header[0]); // Separator
   162→        WriteShort(x); // Position X
   163→        WriteShort(y); // Position Y
   164→        WriteShort(h); // Height
   165→        WriteShort(w); // Width
   166→
   167→        if (includeColorTable) // If first frame, use global color table - else use local
   168→        {
   169→            sourceGif.Position = SourceGlobalColorInfoPosition;
   170→            WriteByte(sourceGif.ReadByte() & 0x3f | 0x80); // Enabling local color table
   171→            WriteColorTable(sourceGif);
   172→        }
   173→        else
   174→        {
   175→            WriteByte(header[9] & 0x07 | 0x07); // Disabling local color table
   176→        }
   177→
   178→        WriteByte(header[10]); // LZW Min Code Size
   179→
   180→        // Read/Write image data
   181→        sourceGif.Position = SourceImageBlockPosition + SourceImageBlockHeaderLength;
   182→
   183→        var dataLength = sourceGif.ReadByte();
   184→        while (dataLength > 0)
